"""Assemble B2 report from completed computations; no model or cache mutation."""
from pathlib import Path
import json
import pandas as pd
import numpy as np
P=Path(__file__).resolve().parent
ROOT=P.parents[3]
def read(n): return pd.read_csv(P/(n+'.csv'))
def save(d,n): d.to_csv(P/(n+'.csv'),index=False,na_rep='NA')
def table(d):
 def fmt(v):
  if pd.isna(v): return 'NA'
  if isinstance(v,(float,np.floating)): return f'{v:.6f}'
  return str(v)
 return '| '+' | '.join(d.columns)+' |\n| '+' | '.join(['---']*len(d.columns))+' |\n'+'\n'.join('| '+' | '.join(fmt(v) for v in row)+' |' for row in d.itertuples(index=False,name=None))+'\n'
