keys=['fold','domain','partition','model','output','method','requested_coverage']
assert (O.accepted_count==O.benign_accepted+O.attack_accepted).all()
assert (O.accepted_errors==O.FP+O.FN).all()
assert (O.accepted_count==O.TN+O.FP+O.FN+O.TP).all()
