kg=K.groupby(keys)[['category_total','accepted_count','correct_accepted_attack_count','wrong_accepted_benign_count','abstained_count']].sum().reset_index().merge(O,on=keys,suffixes=('_cat','_all'),validate='one_to_one')
for a,b in [('category_total','attack_total'),('accepted_count_cat','attack_accepted'),('correct_accepted_attack_count','TP'),('wrong_accepted_benign_count','FN'),('abstained_count','attack_abstained')]: assert (kg[a]==kg[b]).all()
