z=K[(K.partition=='T_heldout')&(K.method=='one_minus_u')].merge(b1,on=['domain','model','output','requested_coverage','original_attack_category'],suffixes=('_b2','_b1'),validate='one_to_one')
assert len(z)==len(K[(K.partition=='T_heldout')&(K.method=='one_minus_u')])
for c in ['category_total','accepted_count','correct_accepted_attack_count','wrong_accepted_benign_count','abstained_count']: assert (z[c+'_b2']==z[c+'_b1']).all()
assert len(F)==18 and (F.status=='COMPLETE').all() and F.converged_gradient.all()
assert (D.monotonicity_violations==0).all()
for row in F.itertuples():
 aud=json.loads(row.training_audits); w=json.loads(row.domain_weights)
 assert all(a['partition']=='R_fit' and a['domain']!=row.target for a in aud)
 assert all(abs(a['rows']*v-row.rows/2)<1e-7 for a,v in zip(aud,w))
